mapper.select:
SELECT e.id, e.user_id, e.item_id, i.name AS item_name, i.cover AS item_cover,
       e.points_cost, e.status, e.address, e.exchange_time,
       u.username, u.nickname
FROM portal_shop_exchange e
LEFT JOIN portal_shop_item i ON e.item_id = i.id
LEFT JOIN portal_user u ON e.user_id = u.id

    and e.status = #{query.status}
    and e.user_id = #{query.userId}
    and e.item_id = #{query.itemId}

order by e.exchange_time desc
